function encryptData(data, key) {
  const cipher = crypto.createCipher('des', key);
  return cipher.update(data, 'utf8', 'hex') + cipher.final('hex');
}

function hashData(data) {
  return crypto.createHash('sha1').update(data).digest('hex');
}

